let datos = msg.payload;

if (Buffer.isBuffer(datos)) {
    datos = datos.toString("utf8");
}

if (typeof datos === "string") {
    try {
        datos = JSON.parse(datos);
    } catch (error) {
        const numero = Number(datos);
        datos = Number.isFinite(numero) ? numero : datos;
    }
}

const topic = msg.topic || "";
let gemelo = flow.get("gemeloDigital") || {
    ultimo_update: null,
    estado_actual: { temperatura: null },
    prediccion_30min: { temperatura: null },
    alertas_activas: []
};

gemelo.ultimo_update = new Date().toISOString();
let csv = null;

if (topic === "smarthome/equipoHector/temperatura") {
    const temperatura = typeof datos === "number" ? datos : Number(datos.temperatura);
    if (Number.isFinite(temperatura)) {
        gemelo.estado_actual.temperatura = temperatura;
        csv = { payload: new Date().toISOString() + "," + temperatura + "\n" };
    }
}

if (topic === "smarthome/equipoHector/prediccion/temperatura") {
    const valor = typeof datos === "number" ? datos : Number(datos.valor ?? datos.temperatura_predicha);
    if (Number.isFinite(valor)) {
        gemelo.prediccion_30min.temperatura = valor;
    }
}

flow.set("gemeloDigital", gemelo);
msg.payload = gemelo;
return [csv, msg];
